/** Load the fixtures into the in memory tables. Idempotent. */
export function seed(users: User[], invoices: Invoice[]): void {
  for (const u of SEED_USERS) if (!users.some((x) => x.id === u.id)) users.push({ ...u });
  for (const i of SEED_INVOICES) if (!invoices.some((x) => x.id === i.id)) invoices.push({ ...i });
}
